// @ts-nocheck
// Hairline figure "mirrors" for naina-kapoor-choomantar-3p. Generated by the murder-mystery-story-tree skill via hairline-create.
// Body is the figure file verbatim; edit with: python scripts/art.py unwrap <this> mirrors.js → look.mjs → wrap.
export default function define(HL, hairline) {
/**
 * Mirrors: four standing mirrors in a dark hall, fanned at odd angles, the last turned to face the wall.
 * The pointer picks the mirror nearest its x and turns it to face you; its neighbours lean after it, less
 * with distance. Three glasses hold a figure. The last one, turned round, holds no one.
 * The slider is how far the neighbours lean, as a share of the way to facing you.
 * The pointer is read against each mirror's rest centre on screen, which never moves.
 */
const {
  Cam, circ, facing, fillet, fit, lerp, open, poly, prism, proj, put, rad, rings, seg, solid,
  tween, tset, tval, tdone, mk, pointer, register, disposer,
} = HL;

const FX = 130, FY = 110, FT = 8, FOOT = 2.5;       // floor, foot of each mirror
const W = 22, H = 36, TH = 3;                       // a mirror: width, height, thickness
const SPOT = [[29, 91], [53, 67], [77, 43], [101, 19]];
const REST = [40, -35, 55, 180];                    // the last stands with its back to us
const FIG = [-3, 3, -1, null];                      // where each glass holds a figure; the last holds none
const NAMES = ["first", "second", "third", "empty"];
const STEP = 45;
const T0 = [Math.SQRT1_2, -Math.SQRT1_2], N0 = [Math.SQRT1_2, Math.SQRT1_2]; // facing us: along the glass, out of it

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let lean = value;
  const C = Cam(45, 0.5, 1.8);
  fit(C, [[0, 0, -FT], [FX, FY, -FT], [FX, 0, -FT], [0, FY, -FT], [29, 91, H + FOOT], [101, 19, H + FOOT], [18, 80, H], [112, 8, H]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // The floor: a plank slab, its seams running away from us.
  const [fr, fi] = rings(0, 0, FX, FY, 6, 2);
  const fl = solid(g);
  put(fl, prism(P, front, fr, fi, -FT, 0));
  let seams = "";
  for (let x = 14; x < FX; x += 14) seams += seg(P(x, 4, 0), P(x, FY - 4, 0));
  mk("path", { d: seams, class: "nf lo" }, g);

  const ms = SPOT.map(([x, y], j) => {
    const [r, i] = rings(x - 9, y - 5, x + 9, y + 5, 3, 0.9);
    put(solid(g), prism(P, front, r, i, 0, FOOT));
    const m = { x, y, j, drawn: NaN, a: tween(REST[j]) };
    m.slab = mk("path", { class: "lo" }, g);
    m.edge = mk("path", {}, g);
    m.face = mk("path", {}, g);
    m.glass = mk("path", { class: "nf lo" }, g);
    m.fig = mk("path", { class: "nf" }, g);
    m.marks = mk("path", { class: "nf lo" }, g);
    return m;
  });

  function draw(m, th) {
    if (th === m.drawn) return;
    m.drawn = th;
    const c = Math.cos(rad(th)), s = Math.sin(rad(th));
    const tx = T0[0] * c + N0[0] * s, ty = T0[1] * c + N0[1] * s, nx = -T0[0] * s + N0[0] * c, ny = -T0[1] * s + N0[1] * c;
    const side = c >= 0 ? 1 : -1;
    const at = (sd) => (u, v) => P(m.x + tx * u + nx * sd * TH / 2, m.y + ty * u + ny * sd * TH / 2, FOOT + v);
    const near = at(side), far = at(-side), w = W / 2;
    const quad = (f) => [f(-w, 0), f(w, 0), f(w, H), f(-w, H)];
    const wide = Math.abs(near(w, 0)[0] - near(-w, 0)[0]) > 8;
    const shape = (pts) => poly(wide ? fillet(pts, [2.5, 2.5, 2.5, 2.5]) : pts);
    const e = s > 0 ? w : -w;
    m.slab.setAttribute("d", shape(quad(far)));
    m.edge.setAttribute("d", poly([near(e, 0), far(e, 0), far(e, H), near(e, H)]));
    m.face.setAttribute("d", shape(quad(near)));
    if (side > 0) {
      const g2 = w - 2.4;
      m.glass.setAttribute("d", poly([near(-g2, 2.6), near(g2, 2.6), near(g2, H - 3), near(-g2, H - 3)]));
      m.marks.setAttribute("d", seg(near(-w + 4, H - 7), near(-w + 10, H - 14)));
      const fx = FIG[m.j];
      m.fig.setAttribute("d", fx == null ? "" :
        poly(circ(3.1, 10).map((q) => near(fx + q.u, H * 0.6 + q.v))) +
        poly(fillet([[-6, H * 0.5], [6, H * 0.5], [4.5, H * 0.2], [-4.5, H * 0.2]].map(([u, v]) => near(fx + u, v)), [2, 2, 1.5, 1.5])));
    } else {
      m.glass.setAttribute("d", "");
      m.fig.setAttribute("d", "");
      m.marks.setAttribute("d", seg(near(-w + 2, 3), near(w - 2, H - 3)) + seg(near(-w + 2, H - 3), near(w - 2, 3)));
    }
  }
  ms.forEach((m) => draw(m, REST[m.j]));
  let lit = 3;
  ms[lit].face.classList.add("hi");

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const m of ms) { draw(m, tval(m.a, now)); if (!tdone(m.a, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  // Which mirror: the one whose rest centre is nearest the pointer's x. Rest centres never move (rule 01).
  const cx = SPOT.map(([x, y]) => P(x, y, FOOT + H / 2)[0]);
  let last = null;
  function choose(p) {
    last = p;
    const a = p ? cx.reduce((best, x, j) => (Math.abs(p[0] - x) < Math.abs(p[0] - cx[best]) ? j : best), 0) : -1;
    const now = performance.now();
    for (const m of ms) {
      const f = a < 0 ? 0 : Math.abs(m.j - a) === 0 ? 1 : lean * Math.pow(0.4, Math.abs(m.j - a) - 1);
      tset(m.a, lerp(REST[m.j], 0, f), now, a < 0 ? 0 : Math.abs(m.j - a) * STEP);
    }
    const on = a < 0 ? 3 : a;
    if (on !== lit) { ms[lit].face.classList.remove("hi"); ms[on].face.classList.add("hi"); lit = on; }
    read.textContent = a < 0 ? "rest" : NAMES[a];
    B.wake();
  }
  bag.add(pointer(stage, { move: (p) => choose(p), leave: () => choose(null) }));
  bag.add(() => svg.replaceChildren());

  return { set: (v) => { lean = v; if (last) choose(last); }, destroy: bag.dispose };
}

hairline({
  name: "mirrors",
  means: "Standing mirrors in a dark hall: turn one to face you and it holds a figure. The last, turned to the wall, holds no one.",
  rules: [1, 2, 3, 4, 5, 6],
  range: [0.15, 0.35, 0.6],
  tour: [[108, 129], [169, 129], [231, 129], [292, 129], null],
  mount,
});
}
